/**
 * Gallery images, generated by `bun run gallery` from the (gitignored)
 * originals in gallery-originals/: `./gallery/<name>.webp` is the full view,
 * `./gallery/thumbs/<name>.webp` the grid tile. Ordered by filename; a leading
 * number (`03-torus-dao`) sets the order and is not part of the id, so the
 * `?image=` URL survives reordering. Dimensions are read at build time
 * (`?size`, see vite-plugins/image-size.ts), so the masonry lays out before
 * any image loads. Files are content-hashed by Vite.
 *
 * Alt text defaults to the humanized id ("torus-dao" → "Torus dao"); set real
 * alt text and a caption below, keyed by id.
 */
import type { ImageSize } from "../../vite-plugins/image-size.ts";

export interface GalleryImage {
	id: string;
	/** Full view (lightbox). */
	src: string;
	/** Grid tile (≤ 1000px wide), also the lightbox's placeholder while `src` loads. */
	thumb: string;
	width: number;
	height: number;
	alt: string;
	caption?: string;
}

