const urls = import.meta.glob<string>("./gallery/*.webp", {
	eager: true,
	query: "?url",
	import: "default",
});
const thumbs = import.meta.glob<string>("./gallery/thumbs/*.webp", {
	eager: true,
	query: "?url",
	import: "default",
});
const sizes = import.meta.glob<ImageSize>("./gallery/*.webp", {
	eager: true,
	query: "?size",
	import: "default",
});

const fileName = (path: string) => path.split("/").pop() ?? path;

/** "./gallery/03-torus-dao.webp" → "torus-dao" (keep in sync with scripts/gallery.ts). */
const toId = (path: string) =>
	fileName(path)
		.replace(/\.[^.]+$/, "")
		.replace(/^\d+-/, "");

const humanize = (id: string) => {
	const words = id.replace(/-+/g, " ").trim();
	return words.charAt(0).toUpperCase() + words.slice(1);
};

export const galleryImages: GalleryImage[] = Object.keys(urls)
	// Numeric-aware, so "9-x" sorts before "10-x" without zero-padding.
	.sort((a, b) => a.localeCompare(b, "en", { numeric: true }))
	.map((path) => {
		const id = toId(path);
		return {
			id,
			src: urls[path],
			thumb: thumbs[`./gallery/thumbs/${fileName(path)}`] ?? urls[path],
			...sizes[path],
			alt: details[id]?.alt ?? humanize(id),
			caption: details[id]?.caption,
		};
	});

export function getGalleryImage(id: string): GalleryImage | undefined {
	return galleryImages.find((image) => image.id === id);
}
